function updateJotFormIframes(queryString){const jotformIframes=document.querySelectorAll('iframe[src*="jotform"], iframe[nitro-lazy-src*="jotform"]');if(jotformIframes.length===0){console.warn('JTS Shortcode JS: No JotForm iframes found');return!1}
let updated=!1;jotformIframes.forEach((iframe,index)=>{if(iframe.dataset.jtsUpdated==='true'){return}
let src=iframe.src||iframe.getAttribute('nitro-lazy-src')||'';if(src.includes('?')){src=src.split('?')[0]}
iframe.dataset.jtsUpdating='true';iframe.src=`${src}?${queryString}&isIframeEmbed=1`;iframe.setAttribute('loading','eager');iframe.dataset.jtsUpdated='true';delete iframe.dataset.jtsUpdating;updated=!0});return updated}
document.addEventListener('DOMContentLoaded',function(){if(typeof Cookies==='undefined'){return}
const trackingElements=document.querySelectorAll('.jts-tracking-params');if(trackingElements.length===0){return}
function getTrackingData(){let utmData={};try{utmData=Cookies.get('rr_utm_data')?JSON.parse(Cookies.get('rr_utm_data')):{}}catch(e){}
let trackingData={utm_source:utmData.utm_source||getParam('utm_source')||'',utm_medium:utmData.utm_medium||getParam('utm_medium')||'',utm_campaign:utmData.utm_campaign||getParam('utm_campaign')||'',utm_term:utmData.utm_term||getParam('utm_term')||'',utm_content:utmData.utm_content||getParam('utm_content')||'',gclid:utmData.gclid||getParam('gclid')||'',lead_source:'',first_click_channel:'',converting_url:window.location.href,referrer_url:Cookies.get('referrer_url')||document.referrer||window.location.hostname,referrer_url_last:Cookies.get('referrer_url_last')||document.referrer||window.location.hostname,landing_page_url:Cookies.get('landing_page_url')||window.location.href,landing_page_url_last:Cookies.get('landing_page_url_last')||window.location.href,google_client_id:Cookies.get('google_cid')||getGoogleCid()||'',urls_browsed:'',vwo_uuid:Cookies.get('_vwo_uuid')||'',vwo_uuid_v2:Cookies.get('_vwo_uuid_v2')||''};if(trackingData.landing_page_url.includes('gclid')||trackingData.landing_page_url.includes('gbraid')||trackingData.landing_page_url.includes('wbraid')||trackingData.landing_page_url.includes('-ppc')||trackingData.landing_page_url.includes('source=bing')||trackingData.landing_page_url.includes('msclkid')||trackingData.landing_page_url.includes('gad_source=1')||trackingData.referrer_url.includes('gclid')||trackingData.referrer_url.includes('msclkid')||trackingData.referrer_url.includes('gbraid')||trackingData.referrer_url.includes('wbraid')){trackingData.lead_source='Digital PPC';trackingData.first_click_channel='Paid Search'}else if(trackingData.landing_page_url.includes('utm_campaign=gbp')||trackingData.landing_page_url.includes('applemaps')||trackingData.referrer_url.includes('google.')||trackingData.referrer_url.includes('bing')||trackingData.referrer_url.includes('yahoo')||trackingData.referrer_url.includes('duckduckgo')){trackingData.lead_source='Digital SEO';trackingData.first_click_channel='Organic Search'}else if(/renaissancerecovery|gratitudelodge|connectionsoc|californiadetox|alliancerecovery|thedistrictrecoverycommunity|addictionhotline/.test(trackingData.referrer_url)&&!trackingData.landing_page_url.includes('msclkid')&&!trackingData.landing_page_url.includes('gbraid')&&!trackingData.landing_page_url.includes('wbraid')&&!trackingData.landing_page_url.includes('gclid')){trackingData.lead_source='Direct';trackingData.first_click_channel='Direct'}else if(trackingData.landing_page_url.includes('utm_source=facebook&utm_medium=paid')){trackingData.lead_source='Facebook Ads';trackingData.first_click_channel='Social Media'}else if(trackingData.referrer_url.includes('facebook.com')&&!trackingData.landing_page_url.includes('utm_source=facebook&utm_medium=paid')){trackingData.lead_source='Facebook Organic';trackingData.first_click_channel='Organic Social'}
try{const history=Cookies.get('user_nav_history')?JSON.parse(Cookies.get('user_nav_history')):[];if(history&&Array.isArray(history)){trackingData.urls_browsed=history.map(entry=>`${entry.url}, ${entry["-"]}`).join('\n')}}catch(e){}
return trackingData}
const trackingData=getTrackingData();const queryString=Object.keys(trackingData).filter(key=>trackingData[key]!=='').map(key=>`${encodeURIComponent(key)}=${encodeURIComponent(trackingData[key])}`).join('&');trackingElements.forEach((trackingElement,index)=>{trackingElement.setAttribute('data-tracking-params',queryString)});updateJotFormIframes(queryString);const observer=new MutationObserver((mutations)=>{mutations.forEach((mutation)=>{if(mutation.addedNodes.length){mutation.addedNodes.forEach((node)=>{if(node.tagName==='IFRAME'&&(node.src.includes('jotform')||node.getAttribute('nitro-lazy-src')?.includes('jotform'))){updateJotFormIframes(queryString)}})}
if(mutation.type==='attributes'&&mutation.target.tagName==='IFRAME'&&!mutation.target.dataset.jtsUpdating){const iframe=mutation.target;if(iframe.src.includes('jotform')||iframe.getAttribute('nitro-lazy-src')?.includes('jotform')){updateJotFormIframes(queryString)}}})});observer.observe(document.body,{childList:!0,subtree:!0,attributes:!0,attributeFilter:['src','nitro-lazy-src']});window.addEventListener('unload',()=>{observer.disconnect()})});function getParam(p){var match=RegExp('[?&]'+p+'=([^&]*)').exec(window.location.search);return match&&decodeURIComponent(match[1].replace(/\+/g,' '))}
function getGoogleCid(){var match=document.cookie.match('(?:^|;)\\s*_ga=([^;]*)');var raw=(match)?decodeURIComponent(match[1]):null;if(raw){match=raw.match(/(\d+\.\d+)$/)}
return(match)?match[1]:''}